INSERT INTO notification_event_outbox (
    event_id, tenant_id, course_id, notification_type, subject_type, subject_id, event_key,
    actor_user_id, message, deep_link, occurred_at, recipient_mode, template_vars_json,
    status, attempt_count, next_attempt_at, created_at, updated_at
) VALUES (
    #{eventId}, #{tenantId}, #{courseId}, #{notificationType}, #{subjectType}, #{subjectId}, #{eventKey},
    #{actorUserId}, #{message}, #{deepLink}, #{occurredAt}, #{recipientMode}, #{templateVarsJson},
    #{status}, 0, #{nextAttemptAt}, #{createdAt}, #{updatedAt}
)
ON DUPLICATE KEY UPDATE id = id

mapper.select:
SELECT 
FROM notification_event_outbox
WHERE tenant_id = #{tenantId}
  AND notification_type = #{notificationType}
  AND subject_type = #{subjectType}
  AND subject_id = #{subjectId}
  AND event_key = #{eventKey}

SELECT 
FROM notification_event_outbox
WHERE id = #{id}
  AND claim_token = #{claimToken}
  AND status = 'PROCESSING'
  AND lease_until > #{now}
FOR UPDATE

mapper.update:
UPDATE notification_event_outbox
SET status = 'PROCESSING',
    claim_token = #{claimToken},
    lease_until = #{leaseUntil},
    attempt_count = attempt_count + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND status IN ('PENDING', 'FAILED_RETRYABLE', 'PROCESSING')
  AND next_attempt_at <= #{now}
  AND (lease_until IS NULL OR lease_until < #{now})

UPDATE notification_event_outbox
SET status = 'DONE', updated_at = #{now}
WHERE id = #{id} AND claim_token = #{claimToken}

UPDATE notification_event_outbox
SET status = 'FAILED_PERMANENT',
    last_error = #{lastError},
    lease_until = NULL,
    updated_at = #{now}
WHERE id = #{id} AND claim_token = #{claimToken}
